// Collection 01 — Laboratory & standard packs.
//
// Every value was read from the product label in the owner's photos
// (public/WhatsApp Unknown 2026-10-09 at 9.16.48 PM). Leave a field out when it
// is not confirmed; the cards only render the fields that are present.
//
// Images are transparent cut-outs generated by scripts/cutout-products.cjs:
// <base>.avif|webp (full), <base>-720.* and <base>-560.* (height in px).

export type ProductImage = {
  /** Path without extension or size suffix. */
  base: string
  /** Pixel size of the full-resolution cut-out. */
  width: number
  height: number
}

export type StandardPackProduct = {
  id: string
  name: string
  /** Concentration / grade line printed under the name. */
  concentration?: string
  packSize?: string
  catNo?: string
  casNo?: string
  formula?: string
  image: ProductImage
  alt: string
  /** Product page; falls back to the chemical finder until pages exist. */
  href?: string
}

export type CardCollection = {
  index: string
  title: string
  copy: string
  products: StandardPackProduct[]
}

